// @FIGURE_CODE_BEGIN
let pathSelection = "Path A (Vertical)";
let t_val = 0.5;

let p1 = { x: -Math.PI/2, y: 2.5 };
let p2 = { x: -Math.PI/2, y: 0.5 };

const demoSteps = [
    {
      "title": "Path A: Constant alignment",
      "narration": "Along the vertical path at x = -π/2, the vector field points straight down. Because the path also points straight down, the field and tangent are perfectly aligned, yielding a steady positive contribution.",
      "state": { "pathSelection": "Path A (Vertical)", "parameterT": 0.5 }
    },
    {
      "title": "Path B: Varying alignment",
      "narration": "Switching to the parabolic path changes the relationship. As the curve sweeps from left to right, its tangent direction changes, passing through field vectors that point down, then right, then up-right.",
      "state": { "pathSelection": "Path B (Parabola)", "parameterT": 0.2 }
    },
    {
      "title": "Accumulating the integral",
      "narration": "Sweep the position slider to trace the curve. The dot product of the local field vector and the tangent vector determines the integral's value at each step: positive when aligned, zero when perpendicular, and negative when opposed.",
      "state": { "pathSelection": "Path B (Parabola)", "parameterT": 0.8 }
    }
];
let currentStep = 0;

let layerBg, layerField, layerAxes, layerPath, layerUI;
let initializedField = false;

setPlotFrame({ xDomain: [-3, 3.5], yDomain: [-1.5, 5], margin: 24 });
layerBg = _plotFrame.draw.group();
layerField = _plotFrame.draw.group();
layerAxes = _plotFrame.draw.group();
layerPath = _plotFrame.draw.group();
layerUI = _plotFrame.draw.group();

function update_t(val) {
    t_val = val;
    drawAll();
}

function applyUserPath(val) {
    pathSelection = val;
    if (val === "Path A (Vertical)") {
        p1 = { x: -Math.PI/2, y: 2.5 };
        p2 = { x: -Math.PI/2, y: 0.5 };
    } else {
        p1 = { x: -1, y: 1 };
        p2 = { x: 2, y: 4 };
    }
}

function applyStep(idx) {
    let step = demoSteps[idx];
    document.getElementById('demoNarration').textContent = step.narration;
    document.getElementById('stepLabel').textContent = `Step ${idx+1} of ${demoSteps.length}`;
    document.getElementById('btnPrev').disabled = (idx === 0);
    document.getElementById('btnNext').disabled = (idx === demoSteps.length - 1);

    let st = step.state;
    if (st.pathSelection) {
        document.getElementById('pathSelectionInput').value = st.pathSelection;
        applyUserPath(st.pathSelection);
    }
    if (st.parameterT !== undefined) {
        document.getElementById('parameterTInput').value = st.parameterT;
        document.getElementById('parameterTVal').value = st.parameterT;
        t_val = st.parameterT;
    }
    drawAll();
}

window.prevStep = function() { if(currentStep > 0) applyStep(--currentStep); };
window.nextStep = function() { if(currentStep < demoSteps.length-1) applyStep(++currentStep); };

// Dragging Logic
let activeDragRef = null;
let dragIsActive = false;

function attachDrag(el, p_ref) {
    el.css('cursor', 'grab');
    function start(e) {
        e.preventDefault(); e.stopPropagation();
        activeDragRef = p_ref; dragIsActive = true;
        el.css('cursor', 'grabbing');
    }
    el.node.addEventListener('mousedown', start);
    el.node.addEventListener('touchstart', function(e) {
        if(e.touches.length > 0) { e.clientX = e.touches[0].clientX; e.clientY = e.touches[0].clientY; start(e); }
    }, {passive:false});
}

function handleMove(clientX, clientY) {
    if (dragIsActive && activeDragRef) {
        let f = _plotFrame;
        let rect = document.getElementById('container').getBoundingClientRect();
        let cx = clientX - rect.left;
        let cy = clientY - rect.top;

        let wx = f.xDomain[0] + (cx - f.margin) / f.sx;
        let wy = f.yDomain[0] + (f.height - f.margin - cy) / f.sy;

        activeDragRef.x = Math.max(f.xDomain[0], Math.min(f.xDomain[1], wx));
        activeDragRef.y = Math.max(f.yDomain[0], Math.min(f.yDomain[1], wy));
        drawAll();
    }
}
document.addEventListener('mousemove', e => handleMove(e.clientX, e.clientY));
document.addEventListener('touchmove', e => {
    if(dragIsActive && e.touches.length > 0) {
        e.preventDefault();
        handleMove(e.touches[0].clientX, e.touches[0].clientY);
    }
}, {passive:false});

function endDrag() {
    dragIsActive = false; activeDragRef = null; drawAll();
}
document.addEventListener('mouseup', endDrag);
document.addEventListener('touchend', endDrag);

// Path Math
function getPc() {
    if (pathSelection === "Path A (Vertical)") {
        return { x: (p1.x + p2.x)/2, y: (p1.y + p2.y)/2 };
    } else {
        let dx = Math.abs(p2.x - p1.x);
        return { x: (p1.x + p2.x)/2, y: Math.min(p1.y, p2.y) - dx*0.8 }; 
    }
}

function getPos(t, pc) {
    let x = (1-t)*(1-t)*p1.x + 2*t*(1-t)*pc.x + t*t*p2.x;
    let y = (1-t)*(1-t)*p1.y + 2*t*(1-t)*pc.y + t*t*p2.y;
    return {x, y};
}

function getDeriv(t, pc) {
    let dx = -2*(1-t)*p1.x + 2*(1-2*t)*pc.x + 2*t*p2.x;
    let dy = -2*(1-t)*p1.y + 2*(1-2*t)*pc.y + 2*t*p2.y;
    return {dx, dy};
}

// Drawing Logic
function drawAxes(g) {
    const f = _plotFrame;
    g.line(plotX(f.xDomain[0]), plotY(0), plotX(f.xDomain[1]), plotY(0)).stroke({width:1.5, color:'#000'});
    g.line(plotX(0), plotY(f.yDomain[0]), plotX(0), plotY(f.yDomain[1])).stroke({width:1.5, color:'#000'});

    g.polygon([
        [plotX(f.xDomain[1]), plotY(0)],
        [plotX(f.xDomain[1])-10, plotY(0)-4],
        [plotX(f.xDomain[1])-10, plotY(0)+4]
    ]).fill('#000');
    g.polygon([
        [plotX(0), plotY(f.yDomain[1])],
        [plotX(0)-4, plotY(f.yDomain[1])+10],
        [plotX(0)+4, plotY(f.yDomain[1])+10]
    ]).fill('#000');

    g.text("x").move(plotX(f.xDomain[1])-15, plotY(0)-25).font({size:16, style:'italic', family:'serif'}).fill('#000');
    g.text("y").move(plotX(0)+10, plotY(f.yDomain[1])+5).font({size:16, style:'italic', family:'serif'}).fill('#000');

    for (let x = Math.ceil(f.xDomain[0]); x <= Math.floor(f.xDomain[1]); x++) {
        if (x !== 0) {
            g.line(plotX(x), plotY(0)-4, plotX(x), plotY(0)+4).stroke({width:1.5, color:'#000'});
            g.text(x.toString()).move(plotX(x), plotY(0)+8).font({size:12, anchor:'middle', family:'serif'}).fill('#000');
        }
    }
    for (let y = Math.ceil(f.yDomain[0]); y <= Math.floor(f.yDomain[1]); y++) {
        if (y !== 0) {
            g.line(plotX(0)-4, plotY(y), plotX(0)+4, plotY(y)).stroke({width:1.5, color:'#000'});
            g.text(y.toString()).move(plotX(0)-8, plotY(y)-14).font({size:12, anchor:'end', family:'serif'}).fill('#000');
        }
    }

    let pX = -Math.PI/2;
    g.line(plotX(pX), plotY(0)-4, plotX(pX), plotY(0)+4).stroke({width:1.5, color:'#000'});
    g.text("-π/2").move(plotX(pX), plotY(0)+8).font({size:13, anchor:'middle', family:'serif'}).fill('#000')
     .attr({ 'paint-order':'stroke', stroke:'#e8f4e8', 'stroke-width':4, 'stroke-linejoin':'round' });
}

function drawField(g) {
    const f = _plotFrame;
    let screenLen = 22; 

    for (let x = -2.5; x <= 3; x += 0.5) {
        for (let y = -1; y <= 4.5; y += 0.5) {
            let fx = Math.cos(x);
            let fy = Math.sin(x);

            let sdx = fx * f.sx;
            let sdy = -fy * f.sy;

            let slen = Math.hypot(sdx, sdy);
            if (slen > 0) {
                sdx = (sdx / slen) * screenLen;
                sdy = (sdy / slen) * screenLen;
            }

            let px1 = plotX(x) - sdx/2;
            let py1 = plotY(y) - sdy/2;
            let px2 = plotX(x) + sdx/2;
            let py2 = plotY(y) + sdy/2;

            g.line(px1, py1, px2, py2).stroke({ width: 1.2, color: '#444' });

            let ang = Math.atan2(py2 - py1, px2 - px1);
            let hl = 4.5;
            g.polygon([
                [px2, py2],
                [px2 - hl*Math.cos(ang - 0.5), py2 - hl*Math.sin(ang - 0.5)],
                [px2 - hl*Math.cos(ang + 0.5), py2 - hl*Math.sin(ang + 0.5)]
            ]).fill('#444');
        }
    }
}

function drawArrowHead(g, x, y, x_from, y_from, color, size) {
    let ang = Math.atan2(y - y_from, x - x_from);
    g.polygon([
        [x, y],
        [x - size*Math.cos(ang - 0.5), y - size*Math.sin(ang - 0.5)],
        [x - size*Math.cos(ang + 0.5), y - size*Math.sin(ang + 0.5)]
