layerBg = _plotFrame.draw.group();
layerField = _plotFrame.draw.group();
layerAxes = _plotFrame.draw.group();
layerPath = _plotFrame.draw.group();
layerUI = _plotFrame.draw.group();

function update_t(val) {
    t_val = val;
    drawAll();
}

function applyUserPath(val) {
    pathSelection = val;
    if (val === "Path A (Vertical)") {
        p1 = { x: -Math.PI/2, y: 2.5 };
        p2 = { x: -Math.PI/2, y: 0.5 };
    } else {
        p1 = { x: -1, y: 1 };
        p2 = { x: 2, y: 4 };
    }
}

function applyStep(idx) {
    let step = demoSteps[idx];
    document.getElementById('demoNarration').textContent = step.narration;
    document.getElementById('stepLabel').textContent = `Step ${idx+1} of ${demoSteps.length}`;
    document.getElementById('btnPrev').disabled = (idx === 0);
    document.getElementById('btnNext').disabled = (idx === demoSteps.length - 1);

    let st = step.state;
    if (st.pathSelection) {
        document.getElementById('pathSelectionInput').value = st.pathSelection;
        applyUserPath(st.pathSelection);
    }
    if (st.parameterT !== undefined) {
        document.getElementById('parameterTInput').value = st.parameterT;
        document.getElementById('parameterTVal').value = st.parameterT;
        t_val = st.parameterT;
    }
    drawAll();
}

window.prevStep = function() { if(currentStep > 0) applyStep(--currentStep); };
window.nextStep = function() { if(currentStep < demoSteps.length-1) applyStep(++currentStep); };

// Dragging Logic
let activeDragRef = null;
let dragIsActive = false;

function attachDrag(el, p_ref) {
    el.css('cursor', 'grab');
    function start(e) {
        e.preventDefault(); e.stopPropagation();
        activeDragRef = p_ref; dragIsActive = true;
        el.css('cursor', 'grabbing');
    }
    el.node.addEventListener('mousedown', start);
    el.node.addEventListener('touchstart', function(e) {
        if(e.touches.length > 0) { e.clientX = e.touches[0].clientX; e.clientY = e.touches[0].clientY; start(e); }
    }, {passive:false});
}

function handleMove(clientX, clientY) {
    if (dragIsActive && activeDragRef) {
        let f = _plotFrame;
        let rect = document.getElementById('container').getBoundingClientRect();
        let cx = clientX - rect.left;
        let cy = clientY - rect.top;

        let wx = f.xDomain[0] + (cx - f.margin) / f.sx;
        let wy = f.yDomain[0] + (f.height - f.margin - cy) / f.sy;

        activeDragRef.x = Math.max(f.xDomain[0], Math.min(f.xDomain[1], wx));
        activeDragRef.y = Math.max(f.yDomain[0], Math.min(f.yDomain[1], wy));
        drawAll();
    }
}
document.addEventListener('mousemove', e => handleMove(e.clientX, e.clientY));
document.addEventListener('touchmove', e => {
    if(dragIsActive && e.touches.length > 0) {
        e.preventDefault();
        handleMove(e.touches[0].clientX, e.touches[0].clientY);
    }
}, {passive:false});

function endDrag() {
    dragIsActive = false; activeDragRef = null; drawAll();
}
document.addEventListener('mouseup', endDrag);
document.addEventListener('touchend', endDrag);

// Path Math
function getPc() {
    if (pathSelection === "Path A (Vertical)") {
        return { x: (p1.x + p2.x)/2, y: (p1.y + p2.y)/2 };
    } else {
        let dx = Math.abs(p2.x - p1.x);
        return { x: (p1.x + p2.x)/2, y: Math.min(p1.y, p2.y) - dx*0.8 }; 
    }
}

function getPos(t, pc) {
    let x = (1-t)*(1-t)*p1.x + 2*t*(1-t)*pc.x + t*t*p2.x;
    let y = (1-t)*(1-t)*p1.y + 2*t*(1-t)*pc.y + t*t*p2.y;
    return {x, y};
}

function getDeriv(t, pc) {
    let dx = -2*(1-t)*p1.x + 2*(1-2*t)*pc.x + 2*t*p2.x;
    let dy = -2*(1-t)*p1.y + 2*(1-2*t)*pc.y + 2*t*p2.y;
    return {dx, dy};
}

// Drawing Logic
function drawAxes(g) {
    const f = _plotFrame;
    g.line(plotX(f.xDomain[0]), plotY(0), plotX(f.xDomain[1]), plotY(0)).stroke({width:1.5, color:'#000'});
    g.line(plotX(0), plotY(f.yDomain[0]), plotX(0), plotY(f.yDomain[1])).stroke({width:1.5, color:'#000'});

    g.polygon([
        [plotX(f.xDomain[1]), plotY(0)],
        [plotX(f.xDomain[1])-10, plotY(0)-4],
        [plotX(f.xDomain[1])-10, plotY(0)+4]
    ]).fill('#000');
    g.polygon([
        [plotX(0), plotY(f.yDomain[1])],
        [plotX(0)-4, plotY(f.yDomain[1])+10],
        [plotX(0)+4, plotY(f.yDomain[1])+10]
    ]).fill('#000');

    g.text("x").move(plotX(f.xDomain[1])-15, plotY(0)-25).font({size:16, style:'italic', family:'serif'}).fill('#000');
    g.text("y").move(plotX(0)+10, plotY(f.yDomain[1])+5).font({size:16, style:'italic', family:'serif'}).fill('#000');

    for (let x = Math.ceil(f.xDomain[0]); x <= Math.floor(f.xDomain[1]); x++) {
        if (x !== 0) {
            g.line(plotX(x), plotY(0)-4, plotX(x), plotY(0)+4).stroke({width:1.5, color:'#000'});
            g.text(x.toString()).move(plotX(x), plotY(0)+8).font({size:12, anchor:'middle', family:'serif'}).fill('#000');
        }
    }
    for (let y = Math.ceil(f.yDomain[0]); y <= Math.floor(f.yDomain[1]); y++) {
        if (y !== 0) {
            g.line(plotX(0)-4, plotY(y), plotX(0)+4, plotY(y)).stroke({width:1.5, color:'#000'});
            g.text(y.toString()).move(plotX(0)-8, plotY(y)-14).font({size:12, anchor:'end', family:'serif'}).fill('#000');
        }
    }

    let pX = -Math.PI/2;
    g.line(plotX(pX), plotY(0)-4, plotX(pX), plotY(0)+4).stroke({width:1.5, color:'#000'});
    g.text("-π/2").move(plotX(pX), plotY(0)+8).font({size:13, anchor:'middle', family:'serif'}).fill('#000')
     .attr({ 'paint-order':'stroke', stroke:'#e8f4e8', 'stroke-width':4, 'stroke-linejoin':'round' });
}

function drawField(g) {
    const f = _plotFrame;
    let screenLen = 22; 

    for (let x = -2.5; x <= 3; x += 0.5) {
        for (let y = -1; y <= 4.5; y += 0.5) {
            let fx = Math.cos(x);
            let fy = Math.sin(x);

            let sdx = fx * f.sx;
            let sdy = -fy * f.sy;

            let slen = Math.hypot(sdx, sdy);
            if (slen > 0) {
                sdx = (sdx / slen) * screenLen;
                sdy = (sdy / slen) * screenLen;
            }

            let px1 = plotX(x) - sdx/2;
            let py1 = plotY(y) - sdy/2;
            let px2 = plotX(x) + sdx/2;
            let py2 = plotY(y) + sdy/2;

            g.line(px1, py1, px2, py2).stroke({ width: 1.2, color: '#444' });

            let ang = Math.atan2(py2 - py1, px2 - px1);
            let hl = 4.5;
            g.polygon([
                [px2, py2],
                [px2 - hl*Math.cos(ang - 0.5), py2 - hl*Math.sin(ang - 0.5)],
                [px2 - hl*Math.cos(ang + 0.5), py2 - hl*Math.sin(ang + 0.5)]
            ]).fill('#444');
        }
    }
}

function drawArrowHead(g, x, y, x_from, y_from, color, size) {
    let ang = Math.atan2(y - y_from, x - x_from);
    g.polygon([
        [x, y],
        [x - size*Math.cos(ang - 0.5), y - size*Math.sin(ang - 0.5)],
        [x - size*Math.cos(ang + 0.5), y - size*Math.sin(ang + 0.5)]
    ]).fill(color);
}

function drawPath(gPath, gUI) {
    let pc = getPc();
    let samples = 50;

    // Base faded curve
    let pts = [];
    for (let i = 0; i <= samples; i++) {
        let pt = getPos(i/samples, pc);
        pts.push([plotX(pt.x), plotY(pt.y)]);
    }
    gPath.polyline(pts).fill('none').stroke({ color: '#ff9999', width: 3, linecap: 'round', linejoin: 'round' });

    // Active integral curve
    if (t_val > 0) {
        let activePts = [];
        let a_samples = Math.max(2, Math.floor(samples * t_val));
        for (let i = 0; i <= a_samples; i++) {
            let pt = getPos(i/a_samples * t_val, pc);
            activePts.push([plotX(pt.x), plotY(pt.y)]);
        }
        gPath.polyline(activePts).fill('none').stroke({ color: '#d62728', width: 4, linecap: 'round', linejoin: 'round' });
    }

    // Direction arrows along the path
    for (let i = 1; i <= 3; i++) {
        let arrowT = i * 0.25;
        let pt = getPos(arrowT, pc);
        let d = getDeriv(arrowT, pc);
        let px = plotX(pt.x);
        let py = plotY(pt.y);
        let ang = Math.atan2(-d.dy, d.dx);
        let hl = 7.5;
        gPath.polygon([
            [px + hl*Math.cos(ang), py + hl*Math.sin(ang)],
            [px + hl*Math.cos(ang + 2.5), py + hl*Math.sin(ang + 2.5)],
            [px + hl*Math.cos(ang - 2.5), py + hl*Math.sin(ang - 2.5)]
        ]).fill('#d62728');
    }

    // Curve Label C
    let midPt = getPos(0.5, pc);
    let dMid = getDeriv(0.5, pc);
    let lenMid = Math.hypot(dMid.dx, dMid.dy) || 1;
    let nx = -dMid.dy / lenMid;
    let ny = dMid.dx / lenMid;
    gPath.text("C").move(plotX(midPt.x + nx*0.35)-6, plotY(midPt.y + ny*0.35)-12)
         .font({size: 20, style: 'italic', family: 'serif'}).fill('#d62728')
         .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    // Draggable Endpoints
    let r1 = gUI.circle(16).center(plotX(p1.x), plotY(p1.y)).fill('#d62728').stroke({width:3, color:'#fff'});
    let r2 = gUI.circle(16).center(plotX(p2.x), plotY(p2.y)).fill('#d62728').stroke({width:3, color:'#fff'});
    attachDrag(r1, p1);
    attachDrag(r2, p2);

    r1.on('mousemove', e => showTooltip('Drag to reshape start point', e)).on('mouseleave', () => hideTooltip());
    r2.on('mousemove', e => showTooltip('Drag to reshape end point', e)).on('mouseleave', () => hideTooltip());

    // Current integration point & vectors
    let curr = getPos(t_val, pc);
    let currD = getDeriv(t_val, pc);

    gUI.circle(16).center(plotX(curr.x), plotY(curr.y)).fill('rgba(255,255,255,0.7)');
    gUI.circle(10).center(plotX(curr.x), plotY(curr.y)).fill('#ff7f0e').stroke({width:2, color:'#fff'});

    // Field Vector F at curr
    const fr = _plotFrame;
    let Fx = Math.cos(curr.x);
    let Fy = Math.sin(curr.x);
    let F_sdx = Fx * fr.sx;
    let F_sdy = -Fy * fr.sy;
    let F_visScale = 0.85; 

    let px_end = plotX(curr.x) + F_sdx * F_visScale;
    let py_end = plotY(curr.y) + F_sdy * F_visScale;
    gUI.line(plotX(curr.x), plotY(curr.y), px_end, py_end).stroke({ color: '#1f77b4', width: 3 });
    drawArrowHead(gUI, px_end, py_end, plotX(curr.x), plotY(curr.y), '#1f77b4', 8);

    gUI.text("F").move(px_end+6, py_end-12).font({size:16, weight:'bold', family:'serif'}).fill('#1f77b4')
       .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    // Tangent Vector r' at curr
    let r_sdx = currD.dx * fr.sx;
    let r_sdy = -currD.dy * fr.sy;
    let T_visScale = 0.22;
    let rx_end = plotX(curr.x) + r_sdx * T_visScale;
    let ry_end = plotY(curr.y) + r_sdy * T_visScale;

    gUI.line(plotX(curr.x), plotY(curr.y), rx_end, ry_end).stroke({ color: '#2ca02c', width: 3 });
    drawArrowHead(gUI, rx_end, ry_end, plotX(curr.x), plotY(curr.y), '#2ca02c', 8);

    gUI.text("r'").move(rx_end+6, ry_end-12).font({size:16, weight:'bold', family:'serif'}).fill('#2ca02c')
       .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    // Update Stats Panel
    let dot = Fx * currD.dx + Fy * currD.dy;
    document.getElementById('val_F').textContent = `⟨${(Fx||0).toFixed(2)}, ${(Fy||0).toFixed(2)}⟩`;
    document.getElementById('val_r').textContent = `⟨${(currD.dx||0).toFixed(2)}, ${(currD.dy||0).toFixed(2)}⟩`;
    document.getElementById('val_dot').textContent = (dot||0).toFixed(2);

    let dotFn = function(u) {
        let p = getPos(u, pc);
        let d = getDeriv(u, pc);
        return Math.cos(p.x)*d.dx + Math.sin(p.x)*d.dy;
    };
    let integral = 0;
    if (t_val > 0) integral = integrateSimpson(dotFn, 0, t_val, 100) || 0;

    document.getElementById('val_int').textContent = integral.toFixed(3);
    document.getElementById('stat_t').textContent = Number(t_val).toFixed(2);
}

function drawAll() {
    const f = _plotFrame;
    if (!initializedField) {
        layerBg.rect(f.width - 2*f.margin, f.height - 2*f.margin).move(f.margin, f.margin).fill('#e8f4e8');
        drawAxes(layerAxes);
        drawField(layerField);
        initializedField = true;
    }
    layerPath.clear();
    layerUI.clear();
    drawPath(layerPath, layerUI);
}

document.addEventListener('fig-resize', function() {
    initializedField = false;
    layerBg.clear();
    layerAxes.clear();
    layerField.clear();
    drawAll();
});

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The line integral of a vector field along a curve accumulates the dot product of the field and the curve's tangent, depending entirely on how the path aligns with the field.
KEY INSIGHT (what students should walk away understanding): A line integral simply adds up the local alignment (dot product) between the vector field and the path's direction at every point along the curve.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
