    pathSelection = val;
    if (val === "Path A (Vertical)") {
        p1 = { x: -Math.PI/2, y: 0.5 };
        p2 = { x: -Math.PI/2, y: 2.5 };
    } else {
        p1 = { x: -1, y: 1 };
        p2 = { x: 2, y: 4 };
