    ]).fill('#000');

    g.text("x").move(plotX(3.5)-15, plotY(0)-25).font({size:16, style:'italic', family:'serif'}).fill('#000');
    g.text("y").move(plotX(0)+10, plotY(5.2)+5).font({size:16, style:'italic', family:'serif'}).fill('#000');

    for (let x = -2; x <= 3; x++) {
        if (x !== 0) {
            g.line(plotX(x), plotY(0)-4, plotX(x), plotY(0)+4).stroke({width:1.5, color:'#000'});
            g.text(x.toString()).move(plotX(x), plotY(0)+8).font({size:12, anchor:'middle', family:'serif'}).fill('#000');
        }
    }
    for (let y = 1; y <= 4; y++) {
        g.line(plotX(0)-4, plotY(y), plotX(0)+4, plotY(y)).stroke({width:1.5, color:'#000'});
        g.text(y.toString()).move(plotX(0)-8, plotY(y)-14).font({size:12, anchor:'end', family:'serif'}).fill('#000');
    }

    let pX = -Math.PI/2;
    g.line(plotX(pX), plotY(0)-4, plotX(pX), plotY(0)+4).stroke({width:1.5, color:'#000'});
    g.text("-π/2").move(plotX(pX), plotY(0)+8).font({size:14, anchor:'middle', family:'serif'}).fill('#000')
     .attr({ 'paint-order':'stroke', stroke:'#e2f0e3', 'stroke-width':4, 'stroke-linejoin':'round' });
}

function drawField(g) {
    const f = _plotFrame;
    let screenLen = 22; 
    let dx_grid = Math.PI / 6;

    for (let i = -4; i <= 6; i++) {
        let x = i * dx_grid;
        for (let y = -1.0; y <= 5.0; y += 0.5) {
            let fx = Math.cos(x);
            let fy = Math.sin(x);

            let sdx = fx * f.sx;
            let sdy = -fy * f.sy;

            let slen = Math.hypot(sdx, sdy);
            if (slen > 0) {
                sdx = (sdx / slen) * screenLen;
                sdy = (sdy / slen) * screenLen;
            }

            let px1 = plotX(x) - sdx/2;
            let py1 = plotY(y) - sdy/2;
            let px2 = plotX(x) + sdx/2;
            let py2 = plotY(y) + sdy/2;

            g.line(px1, py1, px2, py2).stroke({ width: 1.2, color: '#222' });

            let ang = Math.atan2(py2 - py1, px2 - px1);
            let hl = 4.5;
            g.polygon([
                [px2, py2],
                [px2 - hl*Math.cos(ang - 0.4), py2 - hl*Math.sin(ang - 0.4)],
                [px2 - hl*Math.cos(ang + 0.4), py2 - hl*Math.sin(ang + 0.4)]
            ]).fill('#222');
        }
    }
}

function drawArrowHead(g, x, y, x_from, y_from, color, size) {
    let ang = Math.atan2(y - y_from, x - x_from);
    g.polygon([
        [x, y],
        [x - size*Math.cos(ang - 0.4), y - size*Math.sin(ang - 0.4)],
        [x - size*Math.cos(ang + 0.4), y - size*Math.sin(ang + 0.4)]
    ]).fill(color);
}

function drawPath(gPath, gUI) {
    let pc = getPc();
    let samples = 60;

    // Base faded curve
    let pts = [];
    for (let i = 0; i <= samples; i++) {
        let pt = getPos(i/samples, pc);
        pts.push([plotX(pt.x), plotY(pt.y)]);
    }
    gPath.polyline(pts).fill('none').stroke({ color: '#ff9999', width: 3, linecap: 'round', linejoin: 'round' });

    // Active integral curve
    if (t_val > 0) {
        let activePts = [];
        let a_samples = Math.max(2, Math.floor(samples * t_val));
        for (let i = 0; i <= a_samples; i++) {
            let pt = getPos(i/a_samples * t_val, pc);
            activePts.push([plotX(pt.x), plotY(pt.y)]);
        }
        gPath.polyline(activePts).fill('none').stroke({ color: '#e31a1c', width: 4.5, linecap: 'round', linejoin: 'round' });
    }

    // Direction arrows along the path
    let arrowTs = (pathSelection === "Path A (Vertical)") ? [0.5] : [0.18, 0.5, 0.82];
    for (let i = 0; i < arrowTs.length; i++) {
        let arrowT = arrowTs[i];
        let pt = getPos(arrowT, pc);
        let d = getDeriv(arrowT, pc);
        let px = plotX(pt.x);
        let py = plotY(pt.y);
        let ang = Math.atan2(-d.dy, d.dx);
        let hl = 7.5;
        gPath.polygon([
            [px + hl*Math.cos(ang), py + hl*Math.sin(ang)],
            [px + hl*Math.cos(ang + 2.5), py + hl*Math.sin(ang + 2.5)],
            [px + hl*Math.cos(ang - 2.5), py + hl*Math.sin(ang - 2.5)]
        ]).fill('#e31a1c');
    }

    // Curve Label C
    let midPt = getPos(0.5, pc);
    let lblX = plotX(midPt.x) + ((pathSelection === "Path A (Vertical)") ? 12 : 16);
    let lblY = plotY(midPt.y) + ((pathSelection === "Path A (Vertical)") ? -10 : 8);
    gPath.text("C").move(lblX, lblY)
         .font({size: 20, style: 'italic', family: 'serif'}).fill('#e31a1c')
         .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    // Draggable Endpoints
    let r1 = gUI.circle(16).center(plotX(p1.x), plotY(p1.y)).fill('#e31a1c').stroke({width:3, color:'#fff'});
    let r2 = gUI.circle(16).center(plotX(p2.x), plotY(p2.y)).fill('#e31a1c').stroke({width:3, color:'#fff'});
    attachDrag(r1, p1);
    attachDrag(r2, p2);

    r1.on('mousemove', e => showTooltip('Drag to reshape start point', e)).on('mouseleave', () => hideTooltip());
    r2.on('mousemove', e => showTooltip('Drag to reshape end point', e)).on('mouseleave', () => hideTooltip());

    // Current integration point & vectors
    let curr = getPos(t_val, pc);
    let currD = getDeriv(t_val, pc);

    gUI.circle(16).center(plotX(curr.x), plotY(curr.y)).fill('rgba(255,255,255,0.7)');
    gUI.circle(10).center(plotX(curr.x), plotY(curr.y)).fill('#ff7f0e').stroke({width:2, color:'#fff'});

    // Field Vector F at curr
    const fr = _plotFrame;
    let Fx = Math.cos(curr.x);
    let Fy = Math.sin(curr.x);
    let F_sdx = Fx * fr.sx;
    let F_sdy = -Fy * fr.sy;
    let F_visScale = 0.85; 

    let px_end = plotX(curr.x) + F_sdx * F_visScale;
    let py_end = plotY(curr.y) + F_sdy * F_visScale;
    gUI.line(plotX(curr.x), plotY(curr.y), px_end, py_end).stroke({ color: '#1f77b4', width: 3 });
    drawArrowHead(gUI, px_end, py_end, plotX(curr.x), plotY(curr.y), '#1f77b4', 8);

    gUI.text("F").move(px_end+6, py_end-12).font({size:16, weight:'bold', family:'serif'}).fill('#1f77b4')
       .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    // Tangent Vector r' at curr
    let r_sdx = currD.dx * fr.sx;
    let r_sdy = -currD.dy * fr.sy;
    let T_visScale = 0.22;
    let rx_end = plotX(curr.x) + r_sdx * T_visScale;
    let ry_end = plotY(curr.y) + r_sdy * T_visScale;

    gUI.line(plotX(curr.x), plotY(curr.y), rx_end, ry_end).stroke({ color: '#2ca02c', width: 3 });
    drawArrowHead(gUI, rx_end, ry_end, plotX(curr.x), plotY(curr.y), '#2ca02c', 8);

    gUI.text("r'").move(rx_end+6, ry_end-12).font({size:16, weight:'bold', family:'serif'}).fill('#2ca02c')
       .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    // Update Stats Panel
    let dot = Fx * currD.dx + Fy * currD.dy;
    document.getElementById('val_F').textContent = `⟨${(Fx||0).toFixed(2)}, ${(Fy||0).toFixed(2)}⟩`;
    document.getElementById('val_r').textContent = `⟨${(currD.dx||0).toFixed(2)}, ${(currD.dy||0).toFixed(2)}⟩`;
    document.getElementById('val_dot').textContent = (dot||0).toFixed(2);

    let dotFn = function(u) {
        let p = getPos(u, pc);
        let d = getDeriv(u, pc);
        return Math.cos(p.x)*d.dx + Math.sin(p.x)*d.dy;
    };
    let integral = 0;
    if (t_val > 0) integral = integrateSimpson(dotFn, 0, t_val, 100) || 0;

    document.getElementById('val_int').textContent = integral.toFixed(3);
    document.getElementById('stat_t').textContent = Number(t_val).toFixed(2);
}

function drawAll() {
    const f = _plotFrame;
    if (!initializedField) {
        layerBg.rect(plotX(3.4) - plotX(-2.4), plotY(-1.2) - plotY(5.2))
               .move(plotX(-2.4), plotY(5.2))
               .fill('#e2f0e3');
        drawAxes(layerAxes);
        drawField(layerField);
        initializedField = true;
    }
    layerPath.clear();
    layerUI.clear();
    drawPath(layerPath, layerUI);
}

document.addEventListener('fig-resize', function() {
    initializedField = false;
    layerBg.clear();
    layerAxes.clear();
    layerField.clear();
    drawAll();
});

applyStep(0);
window.__markRendered();
